--------------------------------
---- WINDOW / LAYER RULES ------
--------------------------------

-- Cinny: open silently on the special "chat" workspace
hl.window_rule({
    name = "cinny-scratchpad",
    match = { class = "^(cinny)$" },
    workspace = "special:chat silent",
})

hl.layer_rule({ name = "bar-blur", match = { namespace = "^bar$" }, blur = true })
hl.layer_rule({ name = "quicksettings-blur", match = { namespace = "^quicksettings$" }, blur = true, ignore_alpha = 0.5 })
hl.layer_rule({ name = "calendar-blur", match = { namespace = "^calendar$" }, blur = true, ignore_alpha = 0.5 })
hl.layer_rule({ name = "launcher-blur", match = { namespace = "^quickshell:launcher$" }, blur = true, ignore_alpha = 0.5 })
hl.layer_rule({ name = "clipboard-blur", match = { namespace = "^quickshell:clipboard$" }, blur = true, ignore_alpha = 0.5 })

---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

hl.bind(mainMod .. " + T", hl.dsp.exec_cmd("foot"))
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
-- hl.bind(mainMod .. " + W", hl.dsp.exit())
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd("nautilus"))
hl.bind(mainMod .. " + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + Space", hl.dsp.global("quickshell:launcherToggle"))
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd("hyprlock"))
hl.bind(mainMod .. " + Y", hl.dsp.window.pseudo()) -- dwindle
hl.bind(mainMod .. " + U", hl.dsp.layout("togglesplit")) -- dwindle

-- BEST-EFFORT: old `fullscreen, <mode>` dispatcher (0 = fullscreen, 1 = maximize).
-- Arg shape (bare number vs a table) isn't confirmed locally — check behavior after reload.
hl.bind(mainMod .. " + Z", hl.dsp.window.fullscreen(1))
hl.bind(mainMod .. " + SHIFT + Z", hl.dsp.window.fullscreen(0))

hl.bind(mainMod .. " + V", hl.dsp.global("quickshell:clipboardToggle"))

hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("~/.config/hypr/bin/toggle-monitors.sh"))

-- Toggle/hide Cinny (scratchpad)
hl.bind(mainMod .. " + C", hl.dsp.workspace.toggle_special("chat"))

-- Screenshot -> Satty
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd('grim -g "$(slurp)" - | satty --filename - --early-exit --copy-command "wl-copy"'))
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd('grim -g "$(slurp)" - | satty --filename - --fullscreen --output-filename ~/Pictures/Screenshots/satty-$(date +%Y%m%d-%H%M%S).png'))
hl.bind(mainMod .. " + CTRL + P", hl.dsp.exec_cmd('grim -g "$(hyprctl activewindow -j | jq -r \'"\\(.at[0]),\\(.at[1]) \\(.size[0])x\\(.size[1])"\')" - | satty --filename - --early-exit --copy-command "wl-copy"'))

hl.bind(mainMod .. " + R", hl.dsp.exec_cmd("ags quit; ags run"))
hl.bind(mainMod .. " + SHIFT + R", hl.dsp.exec_cmd('hyprctl reload && notify-send "Hyprland" "Config reloaded"'))

-- Call PowerMenu Quickshell
hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd('echo "toggle_power" > /tmp/qs_powermenu'))

-- =========================================
-- MODO POWERMENU (Ativado pelo Quickshell)
-- BEST-EFFORT: hl.define_submap's exact call shape isn't confirmed locally
-- (the stub only shows `fun(name: string, reset_or_fn: string|function, fn?: function)`).
-- Note this submap is never actually entered by any bind in this file, in the
-- original .conf either — nothing here calls a "switch to powermenu submap"
-- dispatcher, so it's ported as-is (presumably Quickshell's own PowerMenu
-- component drives entry/exit externally via hyprctl).
-- Check https://wiki.hypr.land/Configuring/Basics/Binds/#submaps if this errors.
-- =========================================
hl.define_submap("powermenu", function()
    -- [Esc] Fecha o menu mandando a mensagem pro Quickshell de novo
    hl.bind("Escape", hl.dsp.exec_cmd('echo "toggle_power" > /tmp/qs_powermenu'))

    -- Atalhos rápidos (basta apertar a letra)
    hl.bind("S", hl.dsp.exec_cmd("systemctl poweroff")) -- [D]esligar
    hl.bind("R", hl.dsp.exec_cmd("systemctl reboot")) -- [R]einiciar
    hl.bind("U", hl.dsp.exec_cmd("systemctl suspend")) -- [S]uspender
    hl.bind("L", hl.dsp.exit()) -- [L]ogout / Sair
end)
-- =========================================

-- Move focus with mainMod + hjkl
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))

hl.bind(mainMod .. " + CTRL + H", hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + CTRL + L", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + CTRL + K", hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + CTRL + J", hl.dsp.window.move({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

hl.bind(mainMod .. " + CTRL + 1", hl.dsp.workspace.move({ monitor = "eDP-1" }))
hl.bind(mainMod .. " + CTRL + right", hl.dsp.workspace.move({ monitor = "eDP-1" }))
hl.bind(mainMod .. " + CTRL + 2", hl.dsp.workspace.move({ monitor = "HDMI-A-1" }))
hl.bind(mainMod .. " + CTRL + left", hl.dsp.workspace.move({ monitor = "HDMI-A-1" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind("ALT + Tab", hl.dsp.focus({ workspace = "e+1" }))
hl.bind("ALT + SHIFT + Tab", hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + Tab", hl.dsp.global("quickshell:overviewToggle"))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("~/.config/dunst/volume up"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("~/.config/dunst/volume down"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("~/.config/dunst/volume mute"), { locked = true, repeating = true })
